# Code Generated by Sidekick is for learning and experimentation purposes only.

import logging
from datetime import UTC, datetime

from channels import EmailChannel, SMSChannel, WebhookChannel
from models import DeliveryStatus, Notification
from schemas import DispatchResult, NotifyRequest
from sqlalchemy.ext.asyncio import AsyncSession

logger = logging.getLogger(__name__)

# ── Which channels fire for each event ───────────────────────────────────────
EVENT_ROUTING: dict[str, dict] = {
    "payment.authorized": {
        "customer_email": True,
        "customer_sms":   False,
        "merchant_email": False,
        "merchant_webhook": True,
    },
    "payment.captured": {
        "customer_email": True,
        "customer_sms":   False,
        "merchant_email": True,
        "merchant_webhook": True,
    },
    "payment.failed": {
        "customer_email": True,
        "customer_sms":   True,
        "merchant_email": False,
        "merchant_webhook": True,
    },
    "payment.refunded": {
        "customer_email": True,
        "customer_sms":   False,
        "merchant_email": True,
        "merchant_webhook": True,
    },
    "payment.voided": {
        "customer_email": True,
        "customer_sms":   False,
        "merchant_email": False,
        "merchant_webhook": True,
    },
    "fraud.detected": {
        "customer_email": True,
        "customer_sms":   True,
        "merchant_email": True,
        "merchant_webhook": True,
    },
}


class Dispatcher:
    def __init__(self):
        self.email   = EmailChannel()
        self.sms     = SMSChannel()
        self.webhook = WebhookChannel()

    async def dispatch(self, req: NotifyRequest, db: AsyncSession) -> DispatchResult:
        routing   = EVENT_ROUTING.get(req.event, {})
        context   = req.model_dump()
        channels_used: list[str] = []
        queued    = 0

        # ── Customer email ────────────────────────────────────────────────────
        if routing.get("customer_email") and req.customer_email:
            notif = await self._create_notification(db, req, "email", req.customer_email)
            success, error = await self.email.send(req.customer_email, req.event, context)
            await self._update_notification(db, notif, success, error)
            channels_used.append("email:customer")
            queued += 1

        # ── Customer SMS ──────────────────────────────────────────────────────
        if routing.get("customer_sms") and req.customer_phone:
            notif = await self._create_notification(db, req, "sms", req.customer_phone)
            success, error = await self.sms.send(req.customer_phone, req.event, context)
            await self._update_notification(db, notif, success, error)
            channels_used.append("sms:customer")
            queued += 1

        # ── Merchant email ────────────────────────────────────────────────────
        if routing.get("merchant_email") and req.merchant_email:
            notif = await self._create_notification(db, req, "email", req.merchant_email)
            success, error = await self.email.send(req.merchant_email, req.event, context)
            await self._update_notification(db, notif, success, error)
            channels_used.append("email:merchant")
            queued += 1

        # ── Merchant webhook ──────────────────────────────────────────────────
        if routing.get("merchant_webhook"):
            webhook_payload = {
                "event":      req.event,
                "payment_id": req.payment_id,
                "amount":     req.amount,
                "currency":   req.currency,
                "merchant_id": req.merchant_id,
                "metadata":   req.metadata or {},
                "created_at": datetime.now(UTC).isoformat(),
            }
            deliveries = await self.webhook.dispatch(
                db, req.merchant_id, req.event, req.payment_id, webhook_payload,
            )
            if deliveries:
                channels_used.append(f"webhook:{len(deliveries)}")
                queued += len(deliveries)

        logger.info(
            "[DISPATCHER] event=%s payment=%s channels=%s queued=%d",
            req.event, req.payment_id, channels_used, queued,
        )

        return DispatchResult(
            payment_id=req.payment_id,
            event=req.event,
            notifications_queued=queued,
            channels=channels_used,
        )

    # ── Helpers ───────────────────────────────────────────────────────────────
    async def _create_notification(
        self, db: AsyncSession, req: NotifyRequest, channel: str, recipient: str,
    ) -> Notification:
        notif = Notification(
            payment_id  = req.payment_id,
            merchant_id = req.merchant_id,
            event       = req.event,
            channel     = channel,
            recipient   = recipient,
            status      = DeliveryStatus.PENDING,
            metadata_   = req.metadata,
        )
        db.add(notif)
        await db.flush()
        return notif

    async def _update_notification(
        self, db: AsyncSession, notif: Notification, success: bool, error: str | None,
    ):
        notif.status   = DeliveryStatus.SENT if success else DeliveryStatus.FAILED
        notif.attempts = 1
        notif.error    = error
        if success:
            notif.sent_at = datetime.now(UTC)
        await db.commit()
